import pyomo.environ as pyo

DATA = {
    "num_jobs": 5,
    "num_machines": 4,
    "num_positions": 5,
    "processing_time": {
        (0, 0): 9, (0, 1): 9, (0, 2): 7, (0, 3): 6,
        (1, 0): 6, (1, 1): 6, (1, 2): 7, (1, 3): 5,
        (2, 0): 9, (2, 1): 10, (2, 2): 10, (2, 3): 10,
        (3, 0): 6, (3, 1): 10, (3, 2): 6, (3, 3): 10,
        (4, 0): 10, (4, 1): 7, (4, 2): 6, (4, 3): 8,
    },
    "last_position_coeff": {0: 6, 1: 5, 2: 10, 3: 10, 4: 8},
    "big_m": 1000,
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA
    jobs = list(range(d["num_jobs"]))
    machines = list(range(d["num_machines"]))
    positions = list(range(d["num_positions"]))
    p = d["processing_time"]
    coeff = d["last_position_coeff"]
    M = d["big_m"]
    last_pos = max(positions)
    last_machine = max(machines)

    model = pyo.ConcreteModel()

    model.Jobs = pyo.Set(initialize=jobs)
    model.Machines = pyo.Set(initialize=machines)
    model.Positions = pyo.Set(initialize=positions)

    # Binary: job j assigned to schedule position pos
    model.JobSchedule = pyo.Var(
        model.Jobs, model.Positions, within=pyo.Binary
    )

    # Binary: job j immediately precedes job k in the schedule
    model.Precedes = pyo.Var(
        model.Jobs, model.Jobs, within=pyo.Binary
    )

    # Start time of job j on machine m
    model.StartTime = pyo.Var(
        model.Jobs, model.Machines, within=pyo.NonNegativeReals
    )

    # Objective: weighted last-position assignment + start of last job on last machine
    def obj_rule(m):
        return (
            sum(coeff[j] * m.JobSchedule[j, last_pos] for j in m.Jobs)
            + m.StartTime[m.Jobs.last(), last_machine]
        )
    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Each job assigned to exactly one position
    def job_assign_rule(m, j):
        return sum(m.JobSchedule[j, pos] for pos in m.Positions) == 1
    model.JobAssignment = pyo.Constraint(model.Jobs, rule=job_assign_rule)

    # Each position assigned to exactly one job
    def pos_assign_rule(m, pos):
        return sum(m.JobSchedule[j, pos] for j in m.Jobs) == 1
    model.PositionAssignment = pyo.Constraint(
        model.Positions, rule=pos_assign_rule
    )

    # Precedence within a job: next machine starts after current machine finishes
    def job_precedence_rule(m, j, mach):
        if mach == last_machine:
            return pyo.Constraint.Skip
        return (
            m.StartTime[j, mach + 1]
            >= m.StartTime[j, mach] + p[(j, mach)]
        )
    model.JobPrecedence = pyo.Constraint(
        model.Jobs, model.Machines, rule=job_precedence_rule
    )

    # Link Precedes to consecutive schedule positions:
    # if job j is at pos and job k is at pos+1, then Precedes[j,k] = 1
    def precedes_link_rule(m, j, k, pos):
        if pos == last_pos:
            return pyo.Constraint.Skip
        return (
            m.JobSchedule[j, pos] + m.JobSchedule[k, pos + 1]
            - 1
            <= m.Precedes[j, k]
        )
    model.PrecedesLink = pyo.Constraint(
        model.Jobs, model.Jobs, model.Positions, rule=precedes_link_rule
    )

    # No two jobs overlap on the same machine (big-M disjunctive)
    def machine_nonoverlap_rule(m, j, k, mach):
        if j == k:
            return pyo.Constraint.Skip
        return (
            m.StartTime[k, mach]
            >= m.StartTime[j, mach] + p[(j, mach)]
            - M * (1 - m.Precedes[j, k])
        )
    model.MachineNonOverlap = pyo.Constraint(
        model.Jobs, model.Jobs, model.Machines, rule=machine_nonoverlap_rule
    )

    return model
